mapper.select:
SELECT p.* FROM content_photo p
JOIN content_photo_album a ON p.album_id = a.id
WHERE p.family_id = #{familyId}
AND p.deleted = 0 AND a.deleted = 0
ORDER BY p.created_at DESC
LIMIT #{limit}

SELECT p.id FROM content_photo p
WHERE p.deleted = 1 AND p.deleted_at IS NOT NULL AND p.deleted_at < #{cutoff}
  AND NOT EXISTS (SELECT 1 FROM content_photo_album a WHERE a.id = p.album_id AND a.deleted = 1)

mapper.update:
UPDATE content_photo SET deleted = 1, deleted_at = NOW()
WHERE deleted = 0 AND album_id IN
#{id}

UPDATE content_photo SET deleted = 0, deleted_at = NULL
WHERE deleted = 1 AND album_id IN
#{id}
